/* ═══ BrainLab Translation Module ═══ */
/* Dynamic English->Assamese translation layer.
   Uses pre-existing Assamese fields when available,
   falls back to MyMemory API for dynamic translation,
   caches results in localStorage. */
var BrainLabTranslate={
_cache:{},_pending:{},
init:function(){try{this._cache=JSON.parse(localStorage.getItem('bl_tr_cache')||'{}');}catch(e){this._cache={};}},
_saveCache:function(){try{var k=Object.keys(this._cache);if(k.length>800){k.slice(0,k.length-800).forEach(function(key){delete this._cache[key];},this);}localStorage.setItem('bl_tr_cache',JSON.stringify(this._cache));}catch(e){}},
_cacheKey:function(text){return text.trim().substring(0,200);},
_apiTranslate:function(text,cb){
  if(!text||text.length<2){cb(text);return;}
  var url='https://api.mymemory.translated.net/get?q='+encodeURIComponent(text)+'&langpair=en|as';
  var xhr=new XMLHttpRequest();
  xhr.open('GET',url,true);
  xhr.timeout=8000;
  xhr.onreadystatechange=function(){
    if(xhr.readyState===4){
      if(xhr.status===200){
        try{var d=JSON.parse(xhr.responseText);var t=d.responseData.translatedText;
          if(t&&t!=='PLEASE SELECT TWO DISTINCT LANGUAGES'&&t.indexOf('MYMEMORY WARNING')===-1){cb(t);return;}
        }catch(e){}
      }
      cb(text);
    }
  };
  xhr.ontimeout=function(){cb(text);};
  xhr.onerror=function(){cb(text);};
  xhr.send();
},
translateText:function(text,cb){
  if(!text||text.length<2){cb(text);return;}
  var key=this._cacheKey(text);
  if(this._cache[key]){cb(this._cache[key]);return;}
  if(this._pending[key]){var self=this;setTimeout(function(){self.translateText(text,cb);},150);return;}
  this._pending[key]=true;
  var self=this;
  this._apiTranslate(text,function(translated){
    self._cache[key]=translated;self._saveCache();delete self._pending[key];cb(translated);
  });
},
getDisplay:function(q,lang){
  if(lang!=='as'){
    var correctKey='option_'+q.correct_answer;
    return{question:q.question_text,options:{A:q.option_a,B:q.option_b,C:q.option_c,D:q.option_d},explanation:q.explanation,correctText:q[correctKey],needsTranslation:false};
  }
  if(q.question_as&&q.question_as.length>2){
    var ca=q['opt_'+q.correct_answer+'_as']||q['option_'+q.correct_answer];
    return{question:q.question_as,options:{A:q.opt_a_as||q.option_a,B:q.opt_b_as||q.option_b,C:q.opt_c_as||q.option_c,D:q.opt_d_as||q.option_d},explanation:q.exp_as||q.explanation,correctText:ca,needsTranslation:false};
  }
  var eKey='option_'+q.correct_answer;
  return{question:q.question_text,options:{A:q.option_a,B:q.option_b,C:q.option_c,D:q.option_d},explanation:q.explanation,correctText:q[eKey],needsTranslation:true};
},
translateQuestionAsync:function(q,lang,onDone){
  if(lang!=='as'){onDone(null);return;}
  if(q.question_as&&q.question_as.length>2){onDone(null);return;}
  var self=this;
  var texts=[q.question_text,q.option_a,q.option_b,q.option_c,q.option_d,q.explanation||'No explanation available.'];
  var results={};
  var done=0;
  var total=texts.length;
  texts.forEach(function(text,i){
    self.translateText(text,function(translated){
      results[i]=translated;done++;
      if(done===total){
        var ci=['a','b','c','d'].indexOf(q.correct_answer);
        onDone({question:results[0],options:{A:results[1],B:results[2],C:results[3],D:results[4]},explanation:results[5],correctText:results[1+ci]});
      }
    });
  });
}
};

