/* ── 08 Practice Arena ── */
renderPracticeArena:function(){var c=document.getElementById('bl-arena');if(!c)return;var s=this;var h='<div class="bl-carousel">';SA.forEach(function(a){h+='<div class="bl-card bl-fade-in" onclick="BrainLab.startArenaMode(\''+a.mode+'\')"><div class="bl-card-icon">'+a.icon+'</div><div class="bl-card-title">'+a.title+'</div><div class="bl-card-subtitle">'+a.sub+'</div><div class="bl-card-meta"><span class="bl-card-tag">Arena</span></div><button class="bl-card-cta" onclick="event.stopPropagation();BrainLab.startArenaMode(\''+a.mode+'\')">Start</button></div>';});h+='</div>';c.innerHTML=h;},
startArenaMode:function(mode){var s=this;if(mode==='custom'){this.showCustomQuiz();return;}if(mode==='topic'){this.showTopicPicker();return;}if(mode==='difficulty'){this.showDifficultyPicker();return;}var arena=SA.find(function(a){return a.mode===mode;});if(!arena)return;var pool=this.filterQuestions({category:'All'});var selected=this.selectQuestions(pool,arena.count);var qs=this.toQuiz(selected);this._startPlayer({title:arena.title,questions:qs,mode:'arena'});},
showTopicPicker:function(){var s=this;var topics=this.getTopics('All');var h='<div class="bl-modal-overlay" id="bl-tp-modal" onclick="if(event.target===this)this.remove()"><div class="bl-modal-box"><div class="bl-modal-header"><h3>📚 Topic Practice</h3><button class="bl-modal-close" onclick="this.closest(\'.bl-modal-overlay\').remove()">✕</button></div><div class="bl-modal-body">';topics.forEach(function(t){var cnt=s.countByTopic('All',t);h+='<div class="bl-topic-pick" onclick="BrainLab.startTopicSession(\''+t.replace(/'/g,"\\'")+'\')"><span>'+t+'</span><span class="bl-topic-count">'+cnt+' Q</span></div>';});h+='</div></div></div>';var ex=document.createElement('div');ex.innerHTML=h;document.body.appendChild(ex.firstChild);},
