showDifficultyPicker:function(){var s=this;var diffs=[{label:'Easy',val:'easy',icon:'🟢'},{label:'Medium',val:'medium',icon:'🟡'},{label:'Hard',val:'hard',icon:'🔴'}];var h='<div class="bl-modal-overlay" id="bl-dp-modal" onclick="if(event.target===this)this.remove()"><div class="bl-modal-box"><div class="bl-modal-header"><h3>📊 Difficulty Practice</h3><button class="bl-modal-close" onclick="this.closest(\'.bl-modal-overlay\').remove()">✕</button></div><div class="bl-modal-body">';diffs.forEach(function(d){var cnt=s.filterQuestions({difficulty:d.val}).length;h+='<div class="bl-topic-pick" onclick="BrainLab.startDiffSession(\''+d.val+'\')"><span>'+d.icon+' '+d.label+'</span><span class="bl-topic-count">'+cnt+' Q</span></div>';});h+='</div></div></div>';var ex=document.createElement('div');ex.innerHTML=h;document.body.appendChild(ex.firstChild);},
